const setJobEnabled = `-- name: SetJobEnabled :one
UPDATE jobs
SET enabled = $1,
    next_run_at = $2::timestamptz,
    updated_by = $3
WHERE id = $4 AND deleted_at IS NULL
RETURNING id, enabled, schedule, next_run_at, last_scheduled_at, deleted_at, created_at, updated_at, name, slug, description, connection_id, db_mode, databases, exclude, include_globals, retention_keep_last, retention_keep_days, timeout_seconds, verification, expected_window_seconds, created_by, updated_by
`

type SetJobEnabledParams struct {
	Enabled   bool       `json:"enabled"`
	NextRunAt *time.Time `json:"nextRunAt"`
	UpdatedBy *uuid.UUID `json:"updatedBy"`
	ID        uuid.UUID  `json:"id"`
}

func (q *Queries) SetJobEnabled(ctx context.Context, arg SetJobEnabledParams) (Job, error) {
	row := q.db.QueryRow(ctx, setJobEnabled,
		arg.Enabled,
		arg.NextRunAt,
		arg.UpdatedBy,
		arg.ID,
	)
	var i Job
	err := row.Scan(
		&i.ID,
		&i.Enabled,
		&i.Schedule,
		&i.NextRunAt,
		&i.LastScheduledAt,
		&i.DeletedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Name,
		&i.Slug,
		&i.Description,
		&i.ConnectionID,
		&i.DbMode,
		&i.Databases,
		&i.Exclude,
		&i.IncludeGlobals,
		&i.RetentionKeepLast,
		&i.RetentionKeepDays,
		&i.TimeoutSeconds,
		&i.Verification,
		&i.ExpectedWindowSeconds,
		&i.CreatedBy,
		&i.UpdatedBy,
	)
	return i, err
}

const softDeleteJob = `-- name: SoftDeleteJob :execrows
UPDATE jobs
SET deleted_at = now(), enabled = false, next_run_at = NULL, updated_by = $1
WHERE id = $2 AND deleted_at IS NULL
`

type SoftDeleteJobParams struct {
	UpdatedBy *uuid.UUID `json:"updatedBy"`
	ID        uuid.UUID  `json:"id"`
}

// SoftDeleteJob marks a job deleted and unschedules it. Its key, owner and
// destination rows stay (artifacts and the audit log reference them).
func (q *Queries) SoftDeleteJob(ctx context.Context, arg SoftDeleteJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteJob, arg.UpdatedBy, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

